package com.aetherforge.repo;
import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Repository;import java.util.*;
@Repository public class KnowledgeRepository {private final JdbcTemplate db;public KnowledgeRepository(JdbcTemplate db){this.db=db;}public int addDocument(String factoryId,String name,String mime,String content){return db.update("insert into document(factory_id,name,mime_type,status,content) values(?,?,?,'PROCESSED',?)",factoryId,name,mime,content);}public List<Map<String,Object>> documents(){return db.queryForList("select id,name,mime_type,status,created_at from document order by created_at desc");}public void addChunk(String docId,int idx,String content,String embedding){db.update("insert into document_chunk(document_id,chunk_index,content,embedding) values(?,?,?,?::jsonb)",docId,idx,content,embedding);}public List<Map<String,Object>> search(String q){return db.queryForList("select d.id document_id,d.name,c.chunk_index,c.content from document_chunk c join document d on d.id=c.document_id where to_tsvector('simple',c.content) @@ plainto_tsquery('simple',?) order by ts_rank(to_tsvector('simple',c.content),plainto_tsquery('simple',?)) desc limit 8",q,q);}}
